      getIronSettings();
      function getIronSettings() {
        if (STS.ironSettings) {
          var irons = Object.entries(STS.ironSettings);
          irons.forEach(function (i) {
            var name = i[0];
            var value = i[1];
            STS[name] = value;
          });
        } else {
          STS.ironSettings = {};
          var _irons = Object.entries(STS.ironSettings);
          _irons.forEach(function (i) {
            var name = i[0];
            var value = i[1];
            STS[name] = value;
          });
        }
      }
