<li class="products-grid-nav-item active" data-ng-class="{active: 1 == mainCtrl.getPaginationModel('products-grid_1').currentPage}" data-page="1">
<button aria-label="Search" data-ng-click="mainCtrl.getPaginationModel('products-grid_1').currentPage = 1" type="button">
<img alt="Search icon" class="products-grid-item-icon lazy-img js-only" data-lazy-src="https://lh3.googleusercontent.com/_RS8nTX8HLPW-dDr374dEdQTaYn-7LI8HVVk0INaAmk7t8MYZKDssvGnep-GwPR94LJPxqq6UDnbm4tonioTpkl4Kqr6-k-670teZA=h128" data-lazy-threshold="100vh" src="https://lh3.googleusercontent.com/_RS8nTX8HLPW-dDr374dEdQTaYn-7LI8HVVk0INaAmk7t8MYZKDssvGnep-GwPR94LJPxqq6UDnbm4tonioTpkl4Kqr6-k-670teZA=h128"/>
</button>
</li>
